use serde_json::json;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut result = json!([]);
    let mut seen = std::collections::HashMap::new();

    for row in input.as_array().unwrap() {
        let mut row_copy = row.clone();
        row_copy.sort_unstable_by_key(|x| (x[0], x[1]));
        let mut row_copy_str = serde_json::to_string(&row_copy).unwrap();

        if seen.contains_key(&row_copy_str) {
            result = json!([row_copy]);
            continue;
        }

        seen.insert(row_copy_str, true);

        let mut row_copy_int = row_copy.clone();
        row_copy_int.sort_unstable_by_key(|x| x[0]);

        let mut row_copy_int_str = serde_json::to_string(&row_copy_int).unwrap();

        if seen.contains_key(&row_copy_int_str) {
            result = json!([row_copy]);
            continue;
        }

        seen.insert(row_copy_int_str, true);

        result = json!([row_copy]);
    }

    result
}
